["HELPFRAME_GMTALK_ISSUE1"]="Isto inclui informações acerca de: missões, personagens não jogadores (PNJS), itens, lugares ou qualquer outra coisa que o jogador poderá averiguar explorando ou interactuando com o mundo u outros jogadores.",
["HELPFRAME_GMTALK_ISSUE1_HEADER"]="Consejos de jogo",
