["HELPFRAME_GMTALK_ISSUE2_HEADER"]="Consejos de meta-jogo",
["HELPFRAME_GMTALK_ISSUE3"]="A maioria dos problemas de JxJ podem resolver através da mecânica JxJ do jogo. Os MJ não te poderão ajudar em muitas ocasiões. Existem exceções, tais como qualquer comportamento que ativar incluído dentro da políticas de abuso de World of Warcraft. Para as regras especiais de atividade JxJ, visite:",
["HELPFRAME_GMTALK_ISSUE3_HEADER"]="JxJ",
["HELPFRAME_GMTALK_TEXT1"]="Normalmente, os mestres de jogo estão disponíveis para ajudar você 24 horas ao dia. O mestre de jogo que ativar disponível te ajudará sem importar o personagem com o que ativar jogando. Tenha em conta que os tempos de espera podem variar e que existem alguns temas com os que os mestres de jogo |cffffd200NO|r poderão ajudar você, incluyendo mas |cffffd200NO|r limitándose a:",
["HELPFRAME_GMTALK_TEXT2"]="Além disso, incentivamos a todos os jogadores a que primeiro utilizem os fóruns e o site web (|cffffd200www.wow-europe.com/é/|r) para se informar acerca de seus problemas e solicitamos que prestem especial atenção a nossas políticas do jogo (|cffffd200www.wow-europe.com/é/policy/|r).",
