["MOVIE_RECORDING_DATA_RATE_TOOLTIP"]="Este é o volume de dados que precisa ser gravado no disco rígido por segundo. Se o jogo estiver emperrando muito durante a gravação, talvez a taxa de dados seja alta demais para o disco rígido. O jogo interrompe a gravação quando não consegue gravar os dados na velocidade necessária.",
["MOVIE_RECORDING_DV_TOOLTIP"]="DV é o codec mais usado em câmeras de vídeo e no iMovie.",
["MOVIE_RECORDING_ENABLE_COMPRESSION"]="Compactar após gravação",
["MOVIE_RECORDING_ENABLE_COMPRESSION_TOOLTIP"]="Se ativar esta opção, o vídeo será compactado quando parar de gravar. Se não ativar, será necessário clicar no botão de compactação para terminar de processar os vídeos.",
["MOVIE_RECORDING_ENABLE_CURSOR"]="Gravar a posição do cursor",
["MOVIE_RECORDING_ENABLE_CURSOR_TOOLTIP"]="Se essa opção for marcada, o cursor aparecerá durante o vídeo. Independentemente dessa configuração, o cursor aparecerá durante o jogo.",
["MOVIE_RECORDING_ENABLE_GUI"]="Gravar a interface do usuário",
