["MOVIE_RECORDING_ENABLE_ICON"]="Mostrar ícone de gravação",
["MOVIE_RECORDING_ENABLE_ICON_TOOLTIP"]="Se essa opção for marcada, um ícone de câmera de vídeo será exibido na tecido do minimapa durante a gravação. Se a interface do usuário for gravada, isso também aparecerá no vídeo.",
["MOVIE_RECORDING_ENABLE_RECOVER"]="Compactar na conexão",
["MOVIE_RECORDING_ENABLE_RECOVER_TOOLTIP"]="Se marcar esta opção, o jogo oferecerá a chance de compactar, ignorar ou excluir quaisquer vídeos pendentes ao se conectar.",
