["MOVIE_RECORDING_ENABLE_SOUND_TOOLTIP"]="Se essa opção for marcada, o som será gravado no vídeo.",
["MOVIE_RECORDING_FPS_FOURTH"]="1/4 da taxa de quadros do jogo",
["MOVIE_RECORDING_FPS_HALF"]="1/2 da taxa de quadros do jogo",
