["MOVIE_RECORDING_FRAMERATE_TOOLTIP"]="Muda a taxa de quadros do vídeo. Caso escolha um valor fixo, o limite da taxa de quadros do jogo será igual à quantidade de quadros por segundo escolhida. Reduza para melhorar a performance.",
