["MOVIE_RECORDING_H264_TOOLTIP"]="Este codec é suportado de forma nativa por dispositivos da Apple, como iPod, iPhone e AppleTV. Este codec tem a melhor proporção de qualidade/tamanho, porém é mais lento ao compactar.",
["MOVIE_RECORDING_MJPEG"]="MJPEG",
