["MOVIE_RECORDING_MPEG4_TOOLTIP"]="O MPEG-4 é suportado por diversas câmeras digitais e pelo iMovie.",
["MOVIE_RECORDING_QUALITY_TOOLTIP"]="Controla a qualidade do vídeo. Isso afetará a compactação final. O aumento da qualidade também aumenta a quantidade de espaço em disco usada pelo vídeo e a velocidade de compactação.",
["MOVIE_RECORDING_RECORDING"]="Tempo de gravação:",
