["NEWBIE_TOOLTIP_TALENTS"]="Os talentos disponíveis para melhorar e especializar o personagem.",
["NEWBIE_TOOLTIP_TRACKQUEST"]="Adicione ou remova a missão selecionada da lista de missões acompanhadas. É possível clicar em uma missão na lista de missões acompanhadas para visualizar os detalhes.",
["NEWBIE_TOOLTIP_UNIT_DUEL"]="Desafia o jogador selecionado para um duelo. O primeiro jogador a atingir zero pontos de vida perde o duelo.",
["NEWBIE_TOOLTIP_UNIT_FOLLOW"]="Faz com que siga o jogador selecionado. Você seguirá o jogador automaticamente até que o modo de acompanhamento automático seja interrompido.",
["NEWBIE_TOOLTIP_UNIT_FREE_FOR_ALL"]="Seguindo regras de cada um por si, todos os membros do grupo podem saquear um monstro que ajudaram a matar. O dinheiro é dividido automaticamente entre os membros do grupo.",
["NEWBIE_TOOLTIP_UNIT_GROUP_LOOT"]="De acordo com as regras de saque em grupo, os jogadores se revezam no saque, como no modo rodízio, porém todos os membros do grupo têm direito de disputar itens acima do limite de saque.",
["NEWBIE_TOOLTIP_UNIT_INSPECT"]="Inspeciona a armadura e as armas com que o jogador selecionado está equipado.",
