["NEWBIE_TOOLTIP_UNIT_MASTER_LOOTER"]="Nas regras de mestre saqueador, o líder do grupo é o único com permissão para saquear itens no ou acima do limite. Os itens abaixo do limite e o dinheiro são distribuídos de acordo com as regras de rodízio.",
["NEWBIE_TOOLTIP_UNIT_NEED_BEFORE_GREED"]="Seguindo as regras de necessidade antes da ganância, o saque é distribuído em sistema de rodízio. Quaisquer itens acima do valor mínimo de saque são disputados apenas pelos membros do grupo que podem usá-lo.",
["NEWBIE_TOOLTIP_UNIT_OPT_OUT_LOOT"]="Se ativar esta opção, você receberá saque apenas se saquear itens de missões, itens recusados por todos ou se receber saques do mestre saqueador.",
