["Check my breath.  Is it bad enough for you?"]="Que te parece meu fôlego? É o bastante fedido para você?",
["Check this box to override your language setting and use english audio."]="Marque esta opção para ignorar as configurações de idioma e usar o áudio em inglês.",
["Check this option to always display extra actionbars."]="Selecione esta opção para sempre exibir as barras de ações adicionais.",
["Check this option to automatically join the Guild Recruitment chat channel based upon whether or not you are in a guild."]="Marque esta opção para entrar automaticamente no canal de bate-papo de Recrutamento de Guildas, dependendo de você estar ou não em uma guilda.",
["Check this to be able to list the quests in any order you want."]="Marque esta opção para listar as missões na ordem desejada.",
["Check this to enable dynamic reduction of terrain polygon detail.  Check to increase performance."]="Marque esta opção para ativar a redução dinâmica do detalhamento de polígonos do terreno. Marque para melhorar o desempenho.",
["Check this to make quest text appear instantly."]="Marque esta opção para que o texto das missões apareça instantaneamente.",
["Check this to rotate the entire minimap instead of the player arrow."]="Marque esta opção para girar o minimapa em vez da seta do jogador.",
["Check this to show threat on targets as a percentage."]="Marque esta opção para exibir a ameaça nos alvos como percentagem.",
["Check this to sort quests by the distance from their map locations to you."]="Marque esta opção para classificar as missões de acordo com a distância em relação a você.",
["Check this to sort quests in decreasing order of difficulty."]="Marque esta opção para classificar as missões em ordem decrescente de dificuldade.",
["Check this to sort quests in increasing order of difficulty."]="Marque esta opção para classificar as missões em ordem crescente de dificuldade.",
["Check to make the mouse wheel scroll through chat when the cursor is over a chat window."]="Marque esta opção para usar a rolagem da roda do mouse quando o cursor estiver sobre uma janela de bate-papo.",
["Check to maximize window and remove borders."]="Marque esta opção para maximizar a janela e remover as bordas.",
["Check to play in a non-fullscreen window.\n\nIf this is checked the game will use your desktop gamma and you will not be able to adjust it via the slider below."]="Selecione esta opção para sair do modo de janela maximizada.\n\nQuando esta opção é selecionada, o jogo usa o gama da área de trabalho e não é possível ajustá-lo no controle deslizante abaixo.",
["Check to show chat windows immediately upon mouseover."]="Marque esta opção para exibir as janelas de bate-papo imediatamente ao passar o cursor do mouse.",
["Check to track this achievement."]="Marque para listar esta conquista.",
["Check to use the UI Scale Slider, uncheck to use the system default scale."]="Marque esta opção para usar o controle de tamanho da interface do usuário, desmarque para usar o tamanho padrão do sistema.",
["Checking this option will allow you to track this currency type on your backpack.\n\nYou can also Shift-click a currency to add or remove it from your backpack."]="Esta opção permite acompanhar este tipo de moeda na mochila.\n\nTambém é possível segurar Shift e clicar com o botão esquerdo do mouse para adicionar ou remover a moeda da mochila.",
["Checking this will enable additional combat messages to appear in the playfield."]="Se essa opção for selecionada, outras mensagens de combate serão exibidas no campo de batalha.",
["Checking this will hide the interface for tracking zone wide objectives."]="A seleção dessa opção oculta a interface de acompanhamento de objetivos de zonas extensas.",
["Checking this will prevent the deselection of targets by clicking on the gamefield.  Targets can only be cleared by pressing escape or clicking another target."]="Esta opção impede que os alvos sejam desmarcados ao clicar no campo de jogo. Os alvos só podem ser desmarcados ao pressionar Esc ou ao clicar em outro alvo.",
["Checking this will show any selected auction items on your character.\n\nCTRL-Left Clicking any equippable item in the game will also allow you to try it on your character."]="Marcar esta opção mostrará quaisquer itens em leilão do seu personagem.\n\nSegurar a tecla CTRL e clicar com o botão esquerdo do mouse em qualquer item equipável no jogo mostrará o item no personagem.",
