["Congratulations! You just gained a level and became more powerful.|n|nYou can visit your class trainer and see if he or she has new abilities that you can learn."]="Parabéns! Você subiu de nível e ficou mais poderoso.|n|nVisite seu instrutor de classe para descobrir se há novas habilidades disponíveis para aprender.",
["Congratulations, you are a founding member of %s!"]="Parabéns, você é membro fundador de %s!",
["Congratulations, you are a founding member of %s!  To leave, use /teamquit [2v2, 3v3, 5v5]."]="Parabéns, você é membro fundador de %s! Para sair, use /sairequipe [2v2, 3v3, 5v5].",
["Congratulations, you have learned how to summon your first mount. This mighty steed will carry you throughout your adventures in Azeroth and beyond.|n|nTo see all of your mounts, click the |cffffd200Character Info Button|r and look for the Pets tab. You can drag your favorite mount onto your action bar to summon it more easily."]="Parabéns! Você aprendeu a evocar sua primeira montaria. Ela levará você por suas aventuras em Azeroth e além.|n|nPara ver todas as montarias, abra as |cffffd200Informações do Personagem|r e procure a aba de montarias. Você pode arrastar sua montaria favorita para a Barra de Ações e evocá-la com mais facilidade.",
["Congratulations, you have reached level %d!"]="Parabéns! alcançou o nível %d!",
["Congratulations, you have received your first companion. This little fellow will follow you during all of your adventures in Azeroth and beyond.|n|nYou can see all of your companions by clicking the |cffffd200Character Info Button|r and then looking for the Pets tab."]="Parabéns, você recebeu seu primeiro mascote. Este pequeno companheiro seguirá você em suas aventuras por Azeroth e além.|n|nVocê pode ver todos os seus mascotes na aba Mascotes do |cffffd200painel de informações do personagem|r.",
["Congratulations."]="aeeee",
