["Connection lost to Voice Chat service."]="Conexão perdida com o serviço de Bate-papo por voz.",
["Connection/disconnection problems"]="Problemas de conexão/desconexão",
["Consecutive silent characters are not allowed. Create a new name."]="Não é possível utilizar caracteres mudos consecutivos. Escolha um novo nome.",
["Consecutive spaces are not allowed.  Enter a new name."]="Não é possível utilizar espaços consecutivos. Escolha um novo nome.",
