["Continue"]="Continuar",
["Controls"]="Controles",
["Controls how far you can see objects. Decrease to improve performance."]="Controla a distância de visualização de itens. Reduza para melhorar o desempenho.",
["Controls the brightness of the game. Increase brightness until you can clearly see all 21 levels of gray bars below."]="Controla o brilho do jogo. Aumente o brilho até todos os 21 níveis de cinza serem exibidos claramente.",
["Controls the detail level of spell effects.  Decrease to improve performance."]="Controla o nível de detalhe dos efeitos de feitiços. Reduza para melhorar o desempenho.",
["Controls the draw distance of ground clutter items like grass and foliage.  Decrease to improve performance."]="Controla a distância de renderização de detalhes no chão, como grama e folhagem. Reduza para melhorar o desempenho.",
["Controls the intensity of weather effects.  Decrease to improve performance."]="Controla a intensidade dos efeitos climáticos. Reduza para aumentar o desempenho.",
["Controls the level of all texture detail. Decreasing this may slightly improve performance."]="Controla o nível de todos os detalhes de texturas. Reduzir esta opção poderá melhorar um pouco o desempenho.",
["Controls the movie quality. This will affect the final compression. Increasing the quality will also increase the amount of disk space used by the movie and the compression speed."]="Controla a qualidade do vídeo. Isso afetará a compactação final. O aumento da qualidade também aumenta a quantidade de espaço em disco usada pelo vídeo e a velocidade de compactação.",
["Controls the number of ground clutter items, like grass and foliage.  Decrease to improve performance."]="Controla a quantidade de detalhes no chão, como grama e folhagem. Reduza para melhorar o desempenho.",
["Controls the number of particles used in effects caused by spells, fires, etc. Decrease to improve performance."]="Define o número de partículas usadas em efeitos causados por feitiços, fogo etc. Reduza para melhorar o desempenho.",
["Controls the quality of rendered character and environment shadows. Decrease to improve performance."]="Controla qualidade de Renderizados das sombras de personagens e do ambiente. Reduz a qualidade para melhorar o Rendimento.",
["Controls the resolution of player textures. Decreasing this may slightly improve performance."]="Controla a resolução das texturas do jogador. Reduzir esta opção poderá melhorar um pouco o desempenho.",
["Controls whether or not icon links in auto-joined chat channels (such as Trade) are displayed as icons."]="Controla se os links de ícones em canais de bate-papo de participação automática (como Comércio) são exibidos como ícones.",
