["In the upper left corner of your screen is your health bar in green. When your health bar reaches zero, you will die, so be careful.|n|nBelow your health bar is a second bar representing the resource your class uses to power your special abilities, such as rage, energy or mana. Both bars will refill slowly over time."]="No canto superior esquerdo da tela aparecem sua barra de vida em verde. Quando essa barra chegar a zero, morrerá, portanto, tenha cuidado.|n|nBajo sua barra de vida há uma segunda barra que representar o recurso que usa seu classe para suas habilidades especiais, como a raiva, a energia ou o mana. Ambas barras se van reLenando lentamente.",
