["Increases all characters’ chance to Critical Hit. The|namount of the bonus is higher per point on Rogues than|nother classes. Agility affects dodge. Rogues get more|nDodge per point of Agility than other classes. Agility|nadds directly to Armor."]="Aumenta a Chance de Acerto Crítico de todos os personagens. O |nvalor do bônus por ponto é maior para Ladinos do que|noutras classes. Agilidade influencia na esquiva.|nLadinos ganham mais Esquiva por ponto de Agilidade do que|noutras classes. Agilidade afeta diretamente a Armadura.",
