["It takes a long time for loot that you click on or that someone assigns to you to show up in your inventory. It may also take a long time to trade items with another player."]="Demora muito tempo para aparecer no inventário o saque em que clicou ou que lhe foi atribuído. A negociação de itens com outros jogadores também pode ser demorada.",
