["Join the queue to enter this battleground when space becomes available.  This will result in a longer wait than selecting \"First Available\"."]="Entra na fila para participar deste Campo de Batalha quando houver vaga. O tempo de espera é maior do que o da opção \"primeiro disponível\".",
["Join the queue to enter this battleground when space becomes available. This will result in a longer wait than selecting first available."]="Entra na fila para participar deste Campo de Batalha quando houver vaga. O tempo de espera é maior do que o da opção \"primeiro disponível\".",
