["Lag is often caused by having a large number of players in one location, such as a city or Battleground. It can also be caused by high latency between your computer and the WoW servers. Submitting this report will help us detect and hopefully address lag problems you might be experiencing. \n\nWhat type of lag are you experiencing? Click on a button below to submit a report."]="Os atrasos geralmente são causados por uma grande quantidade de jogadores em um local, como uma cidade ou Campo de Batalha. Também podem ser causados por alta latência entre o computador e os servidores do WoW. Enviar o relatório nos ajudará a detectar e, possivelmente, resolver os problemas de atrasos que estiver enfrentando.\n\nQue tipo de atraso está enfrentando? Clique em um botão abaixo para enviar uma reclamação.",
