["Rank is the final result of all the honor system calculations.  Based upon a comparison between your standing for the week versus your current rank, your rank may either rise, fall, or stay the same.  Higher level players rise more quickly in rank (and fall more slowly) than lower level players.  In addition, rank increases more quickly at low ranks than at high ranks."]="Ranque é o resultado final de todos os cálculos do sistema de honra. O seu ranque pode aumentar, diminuir ou continuar o mesmo com base em uma comparação entre a posição semanal e a atual. Jogadores de nível alto aumentam de ranque mais rapidamente (e diminuem mais lentamente) do que jogadores de nível baixo. Além disso, o ranque aumenta mais rapidamente em ranques baixos do que em altos.",
