["Set the camera to always prefer being behind your character."]="Configure a câmera para ficar sempre atrás do seu personagem.",
["Set the camera to be above water when your character is above water, and below water when your character is below water."]="Ajusta a câmera para ficar acima d'água quando o personagem estiver acima d'água e para ficar abaixo d'água quando o personagem estiver abaixo d'água.",
["Set the camera to stay where placed, except when your character is moving."]="Ajuste a câmera para permanecer fixa em uma posição escolhida, exceto quando o personagem estiver se movendo.",
