["So, I have this idea for a great movie.  It's about two Gnomes who find a bracelet of power, and they have to take it to the Burning Steppes and cast it into The Cauldron.  They form the Brotherhood of the Bracelet.  Along the way, they're trailed by a murloc named Gottom who's obsessed with the bracelet, and nine bracelet bogeymen.  It could be a three parter called \"Ruler of the Bracelet\".  The first part would be called \"The Brotherhood of the Bracelet\", followed by \"A Couple of Towers\", with the climactic ending called \"Hey, the King's Back\"."]="\"Tenho uma grande ideia para uma filme. Se trata de dois gnomos que encontram um poderoso bracelete e têm que levá-lo até as Estepas Ardentes e Lançarlo à Caldeirão. Formam a Guilda do Bracelete. Durante o caminho um murloc chamado Gottom, obcecado com o bracelete, os segue. Também nove homens do saco que se o querem roubar. Poderíamos fazer uma trilogia e lhamarla \"O Soberano do Bracelete\". A primeira parte poderá lhamarse \"A Guilda do Bracelete\", seguida de \"Um Par de Torres\", com o culminante final \"Eh, o Rei voltou\".",
["So, an Orc walks into a bar with a parrot on his shoulder.  The bartender says, \"Hey, where'd you get that?\"  The parrot says, \"Durotar.  They got 'em all over the place.\""]="Um orc entrar em um bar com um loro sobre o ombros. O barman lhe diz: \"Ouça, de onde tem sacado essa coisa?\". E o loro lhe responde: \"De Durotar. Ali há muitos\".",
["So, you want to fight for the glory of victory in the games? Well, you're going to have to wait. The Steamwheedle Cartel is taking a break after the great excitement of last season! Come back next week for your shot at glory! Feel free to practice in the meantime, but the true fun will have to wait."]="Assim que que lutar pela glória da vitória nos jogos? Bem, pois vai a ter que esperar. O Cartel Bonvapor se está tomando um descanso atrás a emoção da última temporada! Volta semana que vem para lançar seu disparo à glória! Pode practicar enquanto tanto, mas a verdadeira diversão terá que esperar.",
