["The amount of experience (XP) you have earned. The color of the XP bar indicates your rest state: light blue for Rested, and purple for Normal. Rested players earn twice the experience they would normally gain from slaying a monster. Characters become less rested when they kill monsters, and more rested by spending time at or logging out at an inn or city."]="A quantidade de experiência (EXP) adquirida. A cor da barra de EXP indica o estado de descanso: azul claro para Descansado e roxo para Normal. Jogadores descansados recebem o dobro de experiência por monstros mortos. Os personagens vão se cansando conforme matam monstros e descansam passando tempo ou se desconectando em estalagens ou cidades.",
["The amount of happiness your pet currently has. Content pets inflict normal damage on their enemies, whereas Happy pets inflict enhanced damage, and unhappy pets inflict reduced damage. Happiness goes down when your pet dies or as it grows hungry, while feeding your pet will increase its happiness."]="Nível de felicidade atual do seu mascote. Ajudantes satisfeitos causam dano normal nos inimigos, mas mascotes felizes causam dano maior e mascotes infelizes causam danos reduzidos. A felicidade diminui quando o mascote morre ou fica faminto. Alimentar o mascote aumenta a felicidade dele.",
["The amount of health you currently have. If your health reaches zero, you will die. Health automatically regenerates when you are out of combat."]="O total de pontos de vida que você tem no momento. Se os pontos de vida chegarem a zero, você morrerá. Os pontos de vida se regeneram automaticamente quando você não está em combate.",
["The amount of mana you currently have. Players require mana in order to cast spells. Mana automatically regenerates if you have not cast a spell in the past five seconds."]="O total de mana que você tem no momento. Os jogadores precisam de mana para lançar feitiços. O mana se regenera automaticamente se você ficar cinco segundos sem lançar um feitiço.",
["The array of talents available to enhance and specialize your character."]="Os talentos disponíveis para melhorar e especializar o personagem.",
["The auction house is closed at the moment.|nPlease try again later."]="A casa de leilões está fechada.|nTente novamente mais tarde.",
