["The battle has ended. This arena will close in %s"]="A batalha terminou. Esta arena fechará em %s",
["The battle has ended. This battleground will close in %s"]="A batalha terminou. O campo de batalha fechará em %s",
["The chat entry box will work as it previously did. There will be a single entry box always attached to the primary Chat Frame."]="A caixa de digitação funcionará como anteriormente. Haverá apenas uma caixa de digitação sempre fixa à Janela de Bate-papo principal.",
["The door is locked."]="A porta está trancada.",
["The dungeon you chose does not support players from multiple realms."]="A masmorra selecionada não suporta jogadores de reinos diferentes.",
["The durability of one of your items is getting low. The character icon below your minimap indicates the damaged item in yellow.|n|nFind a vendor in town to repair the item before it breaks."]="A durabilidade de um de seus itens está ficando baixa. O ícone do personagem abaixo do minimapa indica o item danificado em amarelo.|n|nEncontre um comerciante na cidade para consertar o item antes que se quebre.",
