["Today certainly is your day."]="Sem dúvida, hoje é seu dia.",
["Toggle Camera Lock"]="Travar/Destravar câmera",
["Toggle display of the minimap."]="Mostrar/Ocultar minimapa.",
["Toggle on/off the in game Zone Map. Shortcut: Shift-M"]="Mostrar/Ocultar o Mapa de Zonas do jogo. Atalho: Shift-M",
["Toggle text counters for buff durations on and off."]="Ativar/Desativar contadores de duração de bônus.",
["Toggles an additional optional actionbar on the right side of the screen."]="Ativa/Desativa uma barra de ações adicional opcional no lado direito da tecido.",
