["Toggles class colors in the background of Nameplate health bar for enemy players."]="Altera as cores da classe no fundo da barra de vida da placa de nome dos jogadores inimigos no campo de batalha.",
["Toggles displaying of name plates on your pets, totems, and guardians."]="Mostrar/Ocultar as placas de nomes de mascotes, totens e guardiões.",
