["Under free-for-all rules, all group members may loot a monster that they help the group to kill. Money is automatically divided between group members."]="Seguindo regras de cada um por si, todos os membros do grupo podem saquear um monstro que ajudaram a matar. O dinheiro é dividido automaticamente entre os membros do grupo.",
["Under group loot rules, players take turns looting just like in round-robin with the exception that all group members will be eligible to roll for items over the loot threshold."]="De acordo com as regras de saque em grupo, os jogadores se revezam no saque, como no modo rodízio, porém todos os membros do grupo têm direito de disputar itens acima do limite de saque.",
["Under master-looter rules, the group leader is the only group member allowed to loot items at or above the threshold. Items below threshold and money are distributed via the round robin rules."]="Nas regras de mestre saqueador, o líder do grupo é o único com permissão para saquear itens no ou acima do limite. Os itens abaixo do limite e o dinheiro são distribuídos de acordo com as regras de rodízio.",
["Under need-before-greed rules, loot is distributed round-robin style.  Any items over the loot threshold can only be rolled on by group members that can use the item."]="Seguindo as regras de necessidade antes da ganância, o saque é distribuído em sistema de rodízio. Quaisquer itens acima do valor mínimo de saque são disputados apenas pelos membros do grupo que podem usá-lo.",
["Under round-robin rules, group members take turns looting the monsters that they help the group to kill. Money is automatically divided between group members."]="Sob regras de rodízio, os membros do grupo se revezam no saque de monstros que ajudam o grupo a matar. O dinheiro é dividido automaticamente entre os membros do grupo.",
