["When clicking the tab of a Chat Frame, the entry box will attach to it. Each window's entry box will maintain its own saved state and history."]="Ao clicar na aba de uma Janela de Bate-papo, a caixa de digitação se fixará nela. Cada caixa de digitação de janela terá registro e histórico próprios.",
