["You can drink to regain your mana faster. |cffffd200Right Click|r on a beverage to drink it.|n|nYou don't need to drink if your class does not use mana."]="Você pode beber para recuperar o mana mais rapidamente. |cffffd200Clique com o Botão Direito|r em uma bebida para bebê-la.|n|nVocê não precisa beber se sua classe não usar mana.",
["You can eat food to gain health faster. |cffffd200Right Click|r on food to eat it."]="Para regenerar sua vida mais rápido pode comer. Faça |cffffd200clique com o botão direito|r sobre um alimento para comê-lo.",
["You can enter dungeons or find groups for dungeons by using the |cffffd200Dungeon Finder|r. The Dungeon Finder is accessed from the eye button near the middle of your action bar."]="É possível entrar em masmorras ou encontrar grupos para masmorras pelo |cffffd200Localizador de Masmorras|r. O Localizador de Masmorras é acessado pelo botão em forma de olho no centro da barra de ações.",
["You can equip items by first clicking the |cffffd200Character Info Button|r near the bottom of the screen, and then the |cffffd200Backpack Button|r at the bottom right of your screen.|n|nThen just drag an equippable item from your backpack onto your character."]="Você pode se equipar com itens clicando primeiro no |cffffd200Botão Informações do Personagem|r na parte inferior da tecido e, a seguir, no |cffffd200Botão Mochila|r, na parte inferior direita da tecido.|n|nEm seguida, arraste um item equipável da mochila para o personagem.",
["You can find your corpse and resurrect at that location. Players that are level 10 or below can resurrect here with no penalty."]="Você poderá encontrar o cadáver e ressuscitar naquele local. Jogadores de nível 10 ou abaixo podem ressuscitar aqui sem penalidades.",
["You can go to your class trainer to learn new skills. |cffffd200Right Click|r on trainers to talk to them.|n|nTrainers are found in many towns or cities and always in your starting area. You may have to search around a little to find your trainer."]="Você deve falar com o instrutor de classe para aprender novas perícias. |cffffd200Clique com o botão direito do mouse|r nos instrutores para falar com eles.|n|nOs instrutores podem ser encontrados em várias cidades e sempre na área inicial do jogo. Pode ser que precise procurar um pouco até encontrar o instrutor.",
["You can invite another player to your group by |cffffd200Right Clicking|r their portrait and selecting the |cffffd200Invite|r option from the popup menu.|n|nYou can leave a group by Right Clicking on your own portrait and choosing the option to leave the party."]="Você pode convidar outro jogador para o grupo |cffffd200clicando com o Botão Direito do Mouse|r no retrato e selecionando a opção |cffffd200Convidar|r no menu pop-up.|n|nVocê pode sair de um grupo clicando com o Botão Direito do Mouse no seu retrato e escolhendo a opção para sair do grupo.",
["You can learn a new talent in the talent interface.|n|nOpen the talents page by clicking the pulsing |cffffd200Talents Button|r on your action bar."]="Você pode aprender um novo talento na interface de talentos.|n|nAbra a página de talentos clicando no |cffffd200Botão Talentos|r na barra de ações.",
["You can look at your reputation with different groups in the world under the Reputation tab.|n|nClick on the |cffffd200Character Info Button|r to find the Reputation tab."]="É possível verificar a sua reputação com vários grupos do mundo na guia Reputação.|n|nClique no |cffffd200Botão Informações do Personagem|r para acessar a aba Reputação.",
["You can move spells and abilities to your action bar by clicking the |cffffd200Spellbook & Abilities Button|r at the bottom center of the screen and then dragging the ability icon to your action bar.|n|nYou can also use a spell or ability from the Spellbook directly by clicking on it."]="É possível mover feitiços e habilidades para a barra de ação clicando no |cffffd200Botão Grimório e Habilidades|r na parte inferior central da tecido e depois arraste o ícone da habilidade desejada para a barra de ações.|n|nTambém é possível usar um feitiço ou habilidade do Grimório clicando diretamente em seu ícone.",
