["You can respond to that player by hitting the R key and then typing a message, or by typing /tell <theirname> and then the message."]="É possível responder ao jogador pressionando a tecla R e, a seguir, digitando a mensagem ou /falar <nome do jogador>, seguido da mensagem.",
["You can send a message by hitting the Enter key, typing a message, and then hitting Enter again. Other players nearby will hear what you say."]="Você pode enviar uma mensagem pressionando a tecla Enter, digitando a mensagem e, a seguir, pressionando Enter novamente. Os jogadores próximos ouvirão o que você disser.",
["You can turn your character by |cffffd200holding the Right Mouse Button|r and moving the mouse.|n|nYou can look around by holding the Left Mouse Button and moving the mouse."]="É possível girar o personagem |cffffd200mantendo pressionado o Botão Direito do Mouse|r e movendo o mouse.|n|nÉ possível olhar ao redor mantendo pressionado o Botão Esquerdo do Mouse e movendo o mouse.",
