["You have accepted an elite quest. Such quests are best undertaken in a group, for they will take you into areas inhabited by elite creatures.|n|nElite creatures are significantly tougher than normal monsters; however, they are worth more experience. You can tell an elite creature by the golden dragon border around its portrait."]="Você aceitou uma missão elite. Missões desse tipo podem ser cumpridas com mais facilidade em grupo, pois você será levado a áreas habitadas por criaturas elite.|n|nAs criaturas elite são consideravelmente mais fortes do que os monstros normais. No entanto, elas dão mais pontos de experiência. É possível distinguir uma criatura elite pela borda dourada de dragão no retrato.",
