["You have attracted the attention of a hostile creature.|n|nA red glow means the creature is attacking you. A yellow glow means you are in danger of being attacked. An orange glow means the creature is attacking you, but may soon change targets."]="Você atraiu a atenção de uma criatura hostil.|n|nUm brilho vermelho indica que a criatura está atacando você. Um brilho amarelo indica que você corre risco de ser atacado. Um brilho laranja indica que a criatura está atacando você, mas poderá escolher outro alvo em breve.",
