["You have completed your first quest! To collect your reward, you need to turn in the quest to a specific quest giver. Usually this is the same questgiver who gave you the quest.|n|nYou can see nearby questgivers as |cffffd200?|r on your minimap in the upper right of your screen. |cffffd200Right Click|r on a quest giver to talk to him or her."]="Você acabou de concluir sua primeira missão! Para coletar a recompensa deve voltar até um concedente de missão específico, que geralmente é o mesmo que te asignó a missão.|n|nno minimapa situado na esquina superior direita da tela poderá ver aos asignadores de missões mais próximos senhalados com o símbolo |cffffd200?|r. Faça |cffffd200clique com o botão direito|r em um designador de missões para falar com ele.",
