["You have joined a raid group."]="Você entrou em um grupo de raide.",
["You have joined a raid group: a group with an increased limit of 40 members, though usually 10 or 25. Raid groups are necessary to enter the most challenging dungeons or to defeat the most powerful enemies, typically at high level.|n|n|cffff2020While in a raid group, you will not earn credit towards most quests. To leave a raid group, Right Click on your character portrait and select Leave party.|r"]="Você entrou em um grupo de raide, com limite aumentado para 40 membros, mas os mais comuns são de 10 ou 25. É preciso participar de grupos de raide para entrar nas masmorras mais desafiadoras e derrotar os inimigos mais poderosos, geralmente em níveis altos.|n|n|cffff2020Você não receberá créditos para a maioria das missões enquanto estiver em um grupo de raide. Para sair de um grupo, clique com o botão direito do mouse no retrato do seu personagem e selecione Sair do grupo.|r",
["You have joined the guild."]="Você entrou na guilda.",
["You have learned a new ability: %s."]="Você aprendeu uma nova habilidade: %s.",
["You have learned a new spell or ability! Use the |cffffd200Spellbook & Abilities Button|r near the bottom of your screen to open your Spellbook. |cffffd200Left Click and drag|r a spell or ability to move it to your Action Bar.|n|nThe Spellbook is organized by category, as indicated by the tabs sticking out from the right side of the book."]="Você aprendeu um novo feitiço ou habilidade! Use o |cffffd200Botão do Grimório e Habilidades|r na parte inferior da tecido para abrir o Grimório. |cffffd200Clique com o botão esquerdo e arraste|r um feitiço ou habilidade para movê-lo para a Barra de Ações.|n|nO Grimório é organizado por categorias, indicadas pelas abas na lateral direita do livro.",
["You have learned a new spell: %s."]="Você aprendeu um feitiço novo: %s.",
["You have learned everything from that book"]="Você já aprendeu tudo desse livro",
["You have learned how to create a new item: %s."]="Você aprendeu como criar um novo item: %s.",
["You have left the guild."]="Você saiu da guilda.",
["You have left the queue to join a party for %s."]="Você saiu da fila e entrou em um grupo para %s.",
["You have left the raid group."]="Você saiu do grupo de raide.",
["You have lost the title '%s'."]="Você perdeu o título '%s'.",
["You have more than 3 hours of online time. You cannot perform this action during this period. Your rest state will reset in %d hours of offline time. Please go rest. "]="Você está conectado há mais de 3 horas, por isso esta ação não pode ser executada. Seu estado de descanso será reiniciado após permanecer %d horas desconectado. Por favor, vá descansar.",
["You have more than 3 hours of online time. You will receive 1/2 money and XP during this period. Your rest state will reset in %d hours of offline time. Please go rest. "]="Você está conectado há mais de 3 horas. Você receberá 1/2 de dinheiro e de EXP por causa disso. Seu estado de descanso será reiniciado após permanecer %d desconectado. Por favor, vá descansar.",
["You have more than 5 hours of online time. You cannot perform this action. Your rest state will reset in %d hours of offline time. Please log out to get rest and exercise."]="Você está conectado há mais de 5 horas. Não é possível executar esta ação. O seu estado de cansaço voltará ao normal após ficar desconectado por %d horas. Desconecte-se para descansar e fazer exercícios.",
["You have more than 5 hours of online time. You will not be able to gain loot, XP, or complete quests.  Your rest state will reset in %d hours of offline time. Please log out to get rest and exercise."]="Você está conectado há mais de 5 horas. Você não poderá receber saques, EXP e nem completar missões. O seu estado de cansaço voltará ao normal após ficar desconectado por %d horas. Desconecte-se para descansar e fazer exercícios.",
["You have no friend requests"]="Não há solicitações de amizade",
["You have no recently updated stats"]="Não há estatísticas atualizadas recentemente",
["You have no target or your target is too far away."]="Você não tem alvo ou o alvo está longe demais.",
["You have no target."]="Não há alvo.",
["You have nobody to reply to yet."]="Ainda não há ninguém a quem responder.",
["You have not completed the required quest."]="Você ainda não cumpriu a missão necessária.",
["You have not earned any achievements recently"]="Você não obteve nenhuma conquista recentemente",
["You have not earned enough levels to grant any more levels"]="Você não ganhou níveis suficientes para conceder mais níveis",
["You have not spent any talent points."]="Não tem gastado nenhum ponto de talento.",
["You have obtained a ranged weapon. To use it, first equip the weapon by opening your |cffffd200Character Info|r and your |cffffd200Backpack|r and dragging the item onto your character.|n|nThen, open up your |cffffd200Spellbook|r and drag the |cffffd200Shoot|r or |cffffd200Throw|r ability onto your action bar.|n|nOnly hunters, warriors and rogues may use ranged weapons. Mages, priests and warlocks may use wands."]="Você obteve uma arma de longo alcance. Para usá-la, primeiro abra as |cffffd200Informações do Personagem|r e a |cffffd200Mochila|r e arraste o item para o personagem.|n|nA seguir, abra o |cffffd200Grimório|r e arraste a habilidade |cffffd200Atirar|r ou |cffffd200Arremessar|r para a barra de ações.|n|nSomente caçadores, guerreiros e ladinos podem usar armas de longo alcance. Magos, sacerdotes e bruxos podem usar varinhas.",
["You have pending calendar invites."]="Há convites de calendário pendentes.",
["You have reached the in-game cap of unique mail recipients"]="Você atingiu o limite máximo de mensagens para destinatários individuais",
["You have reached your limit of %d |4created event:created events."]="Você atingiu o limite de %d |4evento criado:eventos criados;.",
["You have received a new friend request."]="Você tem uma nova solicitação de amizade.",
["You have received a ticket response. Click here to read it."]="A sua consulta foi respondida. Clique aqui para ler a resposta.",
["You have removed the voice privileges of %s."]="Você revogou os privilégios de voz de %s.",
["You have requested %s's signature."]="Você solicitou a assinatura de %s.",
["You have requested a duel."]="Você solicitou um duelo.",
["You have requested to trade with %s."]="Você pediu para negociar com %s.",
["You have restored the voice privileges of %s."]="Você restituiu os privilégios de voz de %s.",
["You have selected Disenchant for: %s"]="Tem selecionado desencantar para: %s",
["You have selected Greed for: %s"]="Você escolheu Ganância para: %s",
["You have selected Need for: %s"]="Tem selecionado necessidade para: %s",
["You have six different smiles; one for when you're angry, one for when you tear flesh, one for when you chew flesh, one for when you loot bodies, one for when you skin game, and one for when you want to kill something."]="Tem seis sonrisas diferentes. Uma para quando está enfadada, outra para quando desgarras carne, outra para quando masticas carne, outra para quando despojas cuerpos, outra para quando desolhas animais e a última para quando que matar a alguém.",
["You have the maximum number of those gems in your inventory or socketed into items."]="Você tem o máximo dessas gemas no seu inventário ou engastadas em itens.",
["You have the maximum number of those gems socketed into equipped items."]="Você tem o número máximo dessas gemas engastadas em itens equipados.",
["You have to be standing to attack anything!"]="Você precisa ficar de pé para atacar!",
["You have to be unsheathed to do that!"]="Você precisa desembainhar a arma para fazer isto!",
["You have too many of a unique item."]="Você tem unidades demais de um item.",
["You have too many of that item already"]="Você já tem itens demais deste tipo",
["You have too many pets already"]="Você já tem muitos mascotes",
["You have unlearned %s."]="Você desaprendeu %s.",
["You have unread mail"]="Você tem mensagens não lidas",
["You have |cff82c5ff%d|r friend |4request:requests;."]="Você tem |cff82c5ff%d|r |4solicitação:solicitações; de amizade.",
["You haven't reached that taxi node on foot yet!"]="Você primeiro precisa chegar a esse ponto de táxi a pé!",
["You haven't selected a champion"]="Você não selecionou um campeão",
["You joined %s."]="Você entrou em %s.",
["You know I have to keep moving at night or I'll disappear."]="Sabe? Não posso deixar de moverme nem pela noite ou desaparezco.",
["You know how hard it is to get your groove on with the spirit of your great grandmother looking over you?"]="Sabe o difícil que é sentirse leve quando tno Espírito de seu tatarabuela sobre a costas todo dia?",
["You know those Ancient Protectors in Darnassas?  They're not that old."]="Sabe aqueles Protetores Ancestrais de Darnassus? Eles nem são tão velhos assim.",
["You know, I really wish I had a garden where I could put a couple of human statues."]="Sabe? Me adoraria ter um jardim onde colocar um par de estátuas de humanos.",
["You know, Taurens are born hunters.  You ever see a Tauren catch a salmon out of a stream?  It really is quite exciting.  And, have you ever seen a Tauren stalk a python?  'Course you haven't.  That's because Taurens are so adept at blending in with their surroundings."]="Sabe como é: taurens são caçadores natos. Já viu um tauren pegar um salmão no rio? É emocionante. E já viu um tauren perseguir uma serpente? Claro que não. Taurens são especialistas em se misturar ao ambiente.",
["You know, Wisps are actually pretty useful for personal hygiene."]="Sabe? Os fogos fatuos são bastante úteis para higiene pessoal.",
["You know, older bulls really only have one function."]="Sabe? Touros velhos só servem para uma coisa.",
["You know, once you're dead, nothing smells bad anymore.  Rotten eggs?  No problem.  Dead fish?  Like a spring breeze."]="Sabe? Quando está morto, já nada cheira mal. Ovos podres? Não há problema. Peixe morto? Como uma brisa de primavera.",
["You know, squirrels can be deadly when cornered."]="Já sabe que uma ardilha acorralada pode resultar mortal.",
["You leave the group."]="Você sai do grupo.",
["You left %s."]="Você saiu de %s.",
["You look pretty.  I like your hair.  Here's your drink.  Are you ready now?"]="Está guapa. Me gosta seu cabelo. Aí tem seu bebida. Já está lista?",
["You look pretty.  Pretty tasty."]="Está para comerte. Com patatas.",
["You loot %s"]="Você saqueia %s",
["You lose %d experience."]="Você perdeu %d de experiência.",
["You may find that a solution for your issue has already been posted on the Technical Support Forum, located on the World of Warcraft site at:\n\nwww.worldofwarcraft.com\n\nIf your technical issue is not addressed by the solutions posted there, please contact our Technical Support Department:\n\nBy Phone at:  (949) 955-1382\nBy Web at: http://us.blizzard.com/support/index.xml?gameId=11\nBy Email at:  wowtech@blizzard.com"]="Puede que encuentres una solución ya publicada para tu problema en el foro del servicio de Asistencia técnica en el sitio web de World of Warcraft:\n\nwww.wow-europe.com/es/\n\nSi tu problema técnico no aparece allí, ponte en contacto con nuestro Servicio de asistencia técnica:\n\nPor teléfono: 800 099 812 (pulsa 4 para español)\nA través de nuestro sitio web: http://www.wow-europe.com/es/support/technical.html\nPor correo electrónico: wowtechEU@blizzard.com",
["You may not bite other vampires."]="Você não pode morder outros vampiros.",
