["You may not queue for this dungeon."]="Você não pode entrar na fila para esta masmorra.",
["You may not queue for this."]="Você não pode entrar na fila para isto.",
["You may not queue while one or more of your team members is under the effect of restricted play."]="Não é possível entrar na fila quando um ou mais membros da equipe estão com restrições de jogo.",
["You may not trade an item with a temporary enhancement."]="Não é possível negociar um item com encantamento temporário.",
