["You may want to invite other players to team up with you to more easily overcome your enemies.|n|nMany difficult quests can be quickly completed in a group, as quest credit is shared by the group. Moreover, groups earn bonus experience, relative to solo players."]="Você pode convidar outros jogadores para a equipe a fim de derrotar seus inimigos.|n|nMuitas missões difíceis podem ser concluídas rapidamente por um grupo, que compartilha o crédito pela missão. Além disso, grupos ganham mais experiência, em comparação com jogadores individuais.",
